ee:message.ee:set-payload:
%dw 2.0
output application/json

fun transformDate(dateString) = do {
    // Parse with explicit default timezone information
    var parsed = dateString as LocalDateTime {format: "dd MMM yyyy, HH:mm"}
    ---
    parsed as String {format: "yyyy-MM-dd"}
}

fun extractLargeImage(images) =
    (images filter ($.size == "large"))[0]["#text"] default ""

fun extractTags(tagArray) =
    tagArray map $.name

---
(vars.tracks filter (item) -> !item.error?) map (item) -> {
    mbid: item.track.mbid,
    name: item.track.name,
    artist: {
        mbid: item.track.artist.mbid,
        name: item.track.artist.name,
        url: item.track.artist.url
    },
    url: item.track.url,
    imageUrl: extractLargeImage(item.track.album.image),
    date: transformDate(item.track.wiki.published),
    listeners: item.track.listeners as Number,
    playcount: item.track.playcount as Number,
    summary: item.track.wiki.summary,
    tags: extractTags(item.track.toptags.tag)
}
